#!/usr/bin/env bash
# Builds the screenshot demo for the web and captures each screen with
# headless Chrome into docs/screenshots/. Requires Flutter, Node and Chrome.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
HERE="$ROOT/tool/screenshots"
OUT="$ROOT/build/screenshots_web"
PORT="${PORT:-8123}"
FLUTTER="${FLUTTER:-flutter}"

cd "$ROOT"

# Embed the shared demo dataset into Dart.
node -e '
const fs = require("fs");
const json = fs.readFileSync(process.argv[1], "utf8");
fs.writeFileSync(process.argv[2],
  "// GENERATED by tool/screenshots/capture.sh from tool/demo/freelancers.json. Do not edit.\n" +
  "const demoFreelancersJson = r\x27\x27\x27\n" + json + "\x27\x27\x27;\n");
' "$ROOT/tool/demo/freelancers.json" "$HERE/demo_data.g.dart"

"$FLUTTER" build web --release -t tool/screenshots/main_demo.dart \
  --no-web-resources-cdn --output "$OUT"
mkdir -p "$OUT/demo_avatars"
cp "$ROOT"/tool/demo/avatars/*.jpg "$OUT/demo_avatars/"

python3 -m http.server "$PORT" --directory "$OUT" >/dev/null 2>&1 &
SERVER=$!
trap 'kill $SERVER' EXIT
sleep 1

(cd "$HERE" && [ -d node_modules ] || npm install --no-audit --no-fund --silent)
node "$HERE/capture.mjs" "http://localhost:$PORT" "$ROOT/docs/screenshots"
